    var er = pm.variables.replaceIn('{esimResourceId}');
    var eo = pm.variables.replaceIn('{esimOptionId}');
    if (!er || String(er).indexOf('{') >= 0) {
      er = pm.collectionVariables.get('esimResourceId');
    }
    if (!eo || String(eo).indexOf('{') >= 0) {
      eo = pm.collectionVariables.get('esimOptionId');
    }
    var body = JSON.parse(pm.request.body.raw);
    if (er) body.resourceId = String(er);
    if (eo) body.optionId = String(eo);
    pm.request.body.raw = JSON.stringify(body);
  } catch (e) {
    console.warn(label + ': loPatchAvailabilityBodyEsimVars', e);
  }
}
