function loBuildPrebookingDatePlus10Days1030() {
  var d = new Date();
  d.setUTCDate(d.getUTCDate() + 10);
  var pad = function (n) { return n < 10 ? '0' + n : String(n); };
  return d.getUTCFullYear() + '-' + pad(d.getUTCMonth() + 1) + '-' + pad(d.getUTCDate()) + 'T10:30';
}
